input.command:
cd /home/user/fortress; 
sz(){ git ls-tree -r -l $1 -- "$2" 2>/dev/null | awk -v ex="$3" '{ if(ex=="" || $5 !~ ex) s+=$4} END{print s+0}'; }
for d in 2026-10-01 2026-10-10 2026-10-20 2026-11-01 2026-11-05 2026-11-10 2026-11-15 2026-11-20 2026-11-23; do h=$(git rev-list -1 --before="$d 23:59" main); echo "$d $h fr-skill(no sources)=$(sz $h .claude/skills/fortress-repo sources.md) fr-sources=$(git cat-file -s $h:.claude/skills/fortress-repo/references/sources.md 2>/dev/null) coord(no sources)=$(sz $h .claude/skills/coordinator sources.md) FACTS=$(git cat-file -s $h:explorations/coordinator/FACTS.md 2>/dev/null) POS=$(git cat-file -s $h:explorations/coordinator/POSITIONS.md) PLAN=$(git cat-file -s $h:explorations/coordinator/PLAN.md) HELD=$(git cat-file -s $h:explorations/coordinator/HELD.md 2>/dev/null) BOOT=$(git cat-file -s $h:explorations/coordinator/BOOT.md 2>/dev/null) INDEX=$(git cat-file -s $h:explorations/coordinator/INDEX.md) LEDGER=$(git cat-file -s $h:explorations/fortress-gap-ledger.md)"; done
git log --since=2026-11-05 --oneline -- .claude/skills/fortress-repo | wc -l; git log --since=2026-11-05 --oneline -- .claude/skills/coordinator | wc -l

